source.sqlReaderQuery:
SELECT (SELECT PARAMETER_VALUE FROM AZ_PARAMETERS WHERE PARAMETER_NAME = 'OLE_SRC_FACT_ContainerName' AND PIPELINE_NAME = 'Data_Identification' AND DATAFLOW_NAME = 'DFT_FACT_IDENTIFICATION') AS OLE_SRC_FACT_ContainerName,
(SELECT PARAMETER_VALUE FROM AZ_PARAMETERS WHERE PARAMETER_NAME = 'OLE_SRC_FACT_FileName' AND PIPELINE_NAME = 'Data_Identification' AND DATAFLOW_NAME = 'DFT_FACT_IDENTIFICATION') AS OLE_SRC_FACT_FileName,
(SELECT PARAMETER_VALUE FROM AZ_PARAMETERS WHERE PARAMETER_NAME = 'OLE_SRC_FACT_FilePath' AND PIPELINE_NAME = 'Data_Identification' AND DATAFLOW_NAME = 'DFT_FACT_IDENTIFICATION') AS OLE_SRC_FACT_FilePath;
